  if (connectivity_state == GRPC_CHANNEL_READY) {
    // If the subchannel is READY, route the pick to it.
    return PickResult::Complete(subchannel->wrapped_subchannel());
  } else if (connectivity_state == GRPC_CHANNEL_IDLE) {
    // If the subchannel is IDLE, queue the pick and request a connection.
    // The requester deletes itself once the connection has been requested.
    new SubchannelConnectionRequester(std::move(subchannel));
    return PickResult::Queue();
